<script setup lang="ts">
const route=useRoute(),{lang,local}=useLocale(); const {data:service,error}=await useFetch<any>(`/api/catalog/services/${route.params.code}`); if(error.value) throw createError({statusCode:404}); const {data:countries}=await useFetch<any[]>('/api/catalog/countries'); const name=computed(()=>lang.value==='ru'?service.value?.nameRu:service.value?.nameEn)
usePageSeo(computed(()=>lang.value==='ru'?`Виртуальный номер для ${name.value} — SMS-код онлайн`:`Virtual number for ${name.value} — SMS code online`),computed(()=>lang.value==='ru'?`Выберите страну и виртуальный номер для ${name.value}. Узнайте, как работает SMS-верификация, одноразовый код и безопасное подтверждение телефона.`:`Choose a country and virtual number for ${name.value}. Learn how SMS verification and one-time phone codes work.`))
const config=useRuntimeConfig(); useHead({script:[{type:'application/ld+json',innerHTML:computed(()=>JSON.stringify({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:lang.value==='ru'?'Главная':'Home',item:config.public.siteUrl},{'@type':'ListItem',position:2,name:lang.value==='ru'?'Сервисы':'Services',item:`${config.public.siteUrl}/services`},{'@type':'ListItem',position:3,name:name.value,item:`${config.public.siteUrl}/services/${service.value?.code}`}]}))}]})
</script>
<template><div class="shell page"><nav class="crumbs"><NuxtLink :to="local('/services')">{{lang==='ru'?'Сервисы':'Services'}}</NuxtLink> / {{name}}</nav><div class="country-title"><img class="service-hero-icon" :src="`/images/services/${service.code}.webp`" :alt="`${name} logo`"><div><span class="kicker">Service / {{service.code.toUpperCase()}}</span><h1>{{lang==='ru'?`Виртуальные номера для ${name}`:`Virtual numbers for ${name}`}}</h1></div></div><p class="lead">{{lang==='ru'?`Выберите страну, чтобы изучить формат временного номера и SMS-кода подтверждения для ${name}. Доступность зависит от правил приложения, а демонстрационная лента не является реальной доставкой сообщений.`:`Choose a country to explore temporary number and verification-code formats for ${name}. Availability depends on app policies, and the simulated feed is not real delivery.`}}</p><div class="card-grid"><CountryCard v-for="c in countries?.slice(0,24)" :key="c.id" :country="c"/></div><PremiumBanner medium="premium_card"/><SeoCopy :subject="name" type="service"/></div></template>
